const filmstrip=document.querySelector('.gallery-filmstrip-main'),filmstripImage=filmstrip?.querySelector('img'),filmstripCaption=filmstrip?.querySelector('.gallery-filmstrip-caption'),filmstripThumbs=$$('.gallery-thumb');let filmstripTimer;filmstripThumbs.forEach(thumb=>thumb.addEventListener('click',()=>{if(thumb.getAttribute('aria-current')==='true')return;const image=thumb.querySelector('img'),swap=()=>{filmstripImage.src=image.src;filmstripImage.alt=image.alt;filmstripCaption.textContent=image.dataset.caption||'';filmstripThumbs.forEach(x=>x.setAttribute('aria-current',String(x===thumb)));filmstrip.classList.remove('is-changing')};clearTimeout(filmstripTimer);if(matchMedia('(prefers-reduced-motion: reduce)').matches){swap();return}filmstrip.classList.add('is-changing');filmstripTimer=setTimeout(swap,300)}));
