function setFilterBackgroundDisabled(disabled){if(!sheet)return;const targets=[document.querySelector('.site-header'),document.querySelector('.footer-dark'),document.querySelector('.cart-launcher'),document.querySelector('.cart-overlay'),document.querySelector('.cart-drawer'),...$$(':scope > *',sheet.parentElement).filter(x=>x!==sheet)].filter(Boolean);targets.forEach(node=>{if(disabled){node.dataset.filterPreviousAriaHidden=node.getAttribute('aria-hidden')??'';node.inert=true;node.setAttribute('aria-hidden','true')}else{node.inert=false;const previous=node.dataset.filterPreviousAriaHidden;if(previous)node.setAttribute('aria-hidden',previous);else node.removeAttribute('aria-hidden');delete node.dataset.filterPreviousAriaHidden}})}
filterOpen?.addEventListener('click',()=>setFilterBackgroundDisabled(true));document.addEventListener('click',e=>{if(e.target===sheet||e.target.closest?.('.filter-close,.filter-save'))setFilterBackgroundDisabled(false)},{capture:true});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&sheet?.classList.contains('open'))setFilterBackgroundDisabled(false)},{capture:true});
function syncDrawerQuantityUi(){const minus=document.querySelector('[data-qty="-1"]'),plus=document.querySelector('[data-qty="1"]'),label=document.querySelector('.cart-drawer .drawer-header p');if(minus){minus.disabled=cartQty<=1;minus.setAttribute('aria-label','Decrease cart quantity')}if(plus){plus.disabled=cartQty>=99;plus.setAttribute('aria-label','Increase cart quantity')}if(label?.lastChild)label.lastChild.textContent=cartQty===1?' item':' items'}$$('[data-qty]').forEach(button=>button.addEventListener('click',syncDrawerQuantityUi));document.querySelector('.remove-item')?.addEventListener('click',e=>{e.stopImmediatePropagation();cartQty=0;document.querySelector('.drawer-item').hidden=true;document.querySelector('[data-subtotal]').textContent='RM 0';$$('.cart-count').forEach(c=>c.textContent='0');syncDrawerQuantityUi()},{capture:true});document.querySelector('.add-cart')?.addEventListener('click',()=>{document.querySelector('.drawer-item').hidden=false;syncDrawerQuantityUi()});syncDrawerQuantityUi();
