const manifestPath = path.join(root, 'manifest.json')
const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'))
manifest.adaptation = { status: 'needs-ui-review', scope: '9/9 routes rebuilt from Prime Web v2 renderer anatomy', sourceOfTruth: 'src/blocks/** plus owned storefront runtime components', fidelity: 'hierarchy-spacing-responsive-interaction', humanReview: 'pending' }
